def compute(vars):
    europe_stores = vars["v1"]
    total_stores = vars["v2"]

    if total_stores == 0:
        return None

    percentage = (europe_stores / total_stores) * 100

    return {
        "value": percentage,
        "trace": {
            "europe_stores": europe_stores,
            "total_stores": total_stores,
            "percentage": percentage,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "percentage"
            }
        }
    }
